import { spawnSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';

import { checkShim, renderShim, shSingleQuote, writeShim } from '../../src/crew/shim.js';

/** 08 §3.4, verbatim. */
const GOLDEN =
  '#!/bin/sh\n' +
  '# Generated by `kiro-claude crew setup`. Do not edit; rerun setup instead.\n' +
  '# Kiro Crew runs this file as its kiro-cli (KIROCREW_KIRO_BIN). Its probes use a\n' +
  '# minimal environment, so the node and Claude Code paths are fixed here.\n' +
  'KIRO_CLAUDE_BIN="${KIRO_CLAUDE_BIN:-/opt/claude-code/bin/claude}"\n' +
  'export KIRO_CLAUDE_BIN\n' +
  "exec '/opt/node22/bin/node' '/home/u/KIRO-Claude/dist/src/bin/kiro-claude.js' \"$@\"\n";

function tmp(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'kc-shim-'));
}

describe('crew shim (08 §3.4)', () => {
  it('renders the §3.4 golden text byte for byte', () => {
    const text = renderShim({ node: '/opt/node22/bin/node', entry: '/home/u/KIRO-Claude/dist/src/bin/kiro-claude.js', claude: '/opt/claude-code/bin/claude' });
    assert.equal(text, GOLDEN);
    assert.equal(Buffer.byteLength(text), Buffer.byteLength(GOLDEN));
  });

  it('single-quotes paths and escapes embedded quotes as \'\\\'\'', () => {
    assert.equal(shSingleQuote("/a b/it's"), "'/a b/it'\\''s'");
    const text = renderShim({ node: "/o p/no'de", entry: '/e n/kiro-claude.js', claude: '/c l/claude' });
    assert.ok(text.includes(`exec '/o p/no'\\''de' '/e n/kiro-claude.js' "$@"\n`));
    assert.ok(text.includes('KIRO_CLAUDE_BIN="${KIRO_CLAUDE_BIN:-/c l/claude}"\n'));
  });

  it('uses the safe if-form for Claude paths with characters special inside ${…:-…}', () => {
    for (const bad of ['/x/$HOME/claude', '/x/a}b/claude', '/x/a"b/claude', '/x/a`b`/claude', '/x/a\\b/claude']) {
      const text = renderShim({ node: '/n', entry: '/e', claude: bad });
      assert.ok(text.includes(`if [ -z "\${KIRO_CLAUDE_BIN:-}" ]; then KIRO_CLAUDE_BIN=${shSingleQuote(bad)}; fi\n`), bad);
    }
  });

  it('rejects relative paths and newlines', () => {
    assert.throws(() => renderShim({ node: 'node', entry: '/e', claude: '/c' }), /absolute/);
    assert.throws(() => renderShim({ node: '/n', entry: '/e\n', claude: '/c' }), /newline/);
    assert.throws(() => renderShim({ node: '/n', entry: '/e', claude: '' }), /empty/);
  });

  it('writes 0755 atomically, keeps identical bytes untouched (same inode/mtime), rewrites on change', () => {
    const d = tmp();
    const f = path.join(d, 'bin', 'kiro-claude');
    const spec = { node: process.execPath, entry: '/e/kiro-claude.js', claude: '/c/claude' };
    assert.equal(writeShim(f, spec).changed, true);
    assert.equal(fs.statSync(f).mode & 0o777, 0o755);
    const st1 = fs.statSync(f);
    assert.equal(writeShim(f, spec).changed, false);
    const st2 = fs.statSync(f);
    assert.equal(st2.ino, st1.ino);
    assert.equal(st2.mtimeMs, st1.mtimeMs);
    fs.chmodSync(f, 0o700);
    assert.equal(writeShim(f, spec).changed, false);
    assert.equal(fs.statSync(f).mode & 0o777, 0o755, 'mode repaired in place');
    assert.equal(writeShim(f, { ...spec, claude: '/other/claude' }).changed, true);
    assert.ok(fs.readFileSync(f, 'utf8').includes('/other/claude'));
    fs.rmSync(d, { recursive: true, force: true });
  });

  it('refuses to name the shim kiro-cli or kiro-cli-chat (KC-BIN-01)', () => {
    const d = tmp();
    for (const n of ['kiro-cli', 'kiro-cli-chat']) assert.throws(() => writeShim(path.join(d, n), { node: '/n', entry: '/e', claude: '/c' }), /refusing/);
    fs.rmSync(d, { recursive: true, force: true });
  });

  it('checkShim reports missing, non-executable and stale shims', () => {
    const d = tmp();
    const f = path.join(d, 'kiro-claude');
    const spec = { node: '/n', entry: '/e', claude: '/c' };
    assert.match(checkShim(f, spec).problems.join(), /does not exist/);
    writeShim(f, spec);
    assert.deepEqual(checkShim(f, spec), { ok: true, problems: [] });
    assert.match(checkShim(f, { ...spec, entry: '/other' }).problems.join(), /content differs/);
    fs.chmodSync(f, 0o644);
    assert.match(checkShim(f, spec).problems.join(), /not executable/);
    fs.rmSync(d, { recursive: true, force: true });
  });

  it('runs under a minimal env: baked KIRO_CLAUDE_BIN default, env value still wins, args passed verbatim', () => {
    const d = tmp();
    const entry = path.join(d, 'entry.mjs');
    fs.writeFileSync(entry, 'process.stdout.write(JSON.stringify({bin: process.env.KIRO_CLAUDE_BIN, args: process.argv.slice(2)}));\n');
    const f = path.join(d, 'with space', 'kiro-claude');
    writeShim(f, { node: process.execPath, entry, claude: '/baked/claude' });
    const probe = { HOME: d, PATH: '/usr/bin:/bin', LANG: 'C.UTF-8', NO_COLOR: '1', TERM: 'dumb' };
    let r = spawnSync(f, ['acp', '--help', 'a b', "it's", '$HOME'], { env: probe, encoding: 'utf8' });
    assert.equal(r.status, 0, r.stderr);
    assert.deepEqual(JSON.parse(r.stdout), { bin: '/baked/claude', args: ['acp', '--help', 'a b', "it's", '$HOME'] });
    r = spawnSync(f, ['--version'], { env: { ...probe, KIRO_CLAUDE_BIN: '/from/env' }, encoding: 'utf8' });
    assert.equal(JSON.parse(r.stdout).bin, '/from/env');
    // if-form behaves the same
    const g = path.join(d, 'kiro-claude2');
    writeShim(g, { node: process.execPath, entry, claude: '/weird/$x}/claude' });
    r = spawnSync(g, [], { env: probe, encoding: 'utf8' });
    assert.equal(JSON.parse(r.stdout).bin, '/weird/$x}/claude');
    r = spawnSync(g, [], { env: { ...probe, KIRO_CLAUDE_BIN: '/env' }, encoding: 'utf8' });
    assert.equal(JSON.parse(r.stdout).bin, '/env');
    fs.rmSync(d, { recursive: true, force: true });
  });
});
